#!/usr/bin/env python3
from pathlib import Path
import base64
import gzip
import hashlib
import json

ROOT = Path(__file__).resolve().parents[1]
TOOLS = ROOT / "tools"
JAVA = ROOT / "src/main/java/kr/moonseungjun/arcanecircle"
OLD_VERSION = "0.12.1-alpha.2"
NEW_VERSION = "0.12.1-alpha.3"

PAYLOADS = {
    JAVA / "client/WorldMagicTracker.java": (
        "8b85b0939ea5a86d378fd261068280164c9c03e363d4dd9c46f80ffed8d57a83",
        ""
    ),
    JAVA / "client/SignatureGeometry.java": (
        "e26df23253ea7ff7bba8010997a8e448e2c6f8ea68d3f02955330d34f998d1ca",
        ""
    ),
    TOOLS / "test_v0121_alpha3_geometry_perf.py": (
        "7e206388c867fb50445157b53a145645dba0910edb30d67ae69982be754d95d5",
        ""
    ),
}

def install(path: Path, expected: str, encoded: str) -> None:
    raw = gzip.decompress(base64.b64decode(encoded))
    actual = hashlib.sha256(raw).hexdigest()
    if actual != expected:
        raise RuntimeError(f"payload digest mismatch for {path}: {actual}")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(raw)

def replace_version(path: Path) -> None:
    text = path.read_text(encoding="utf-8")
    if NEW_VERSION in text:
        return
    if OLD_VERSION not in text:
        raise RuntimeError(f"unexpected version in {path}")
    path.write_text(text.replace(OLD_VERSION, NEW_VERSION), encoding="utf-8")

for path, (expected, encoded) in PAYLOADS.items():
    install(path, expected, encoded)

replace_version(ROOT / "gradle.properties")
replace_version(JAVA / "ArcaneCircle.java")

index_path = ROOT / "src/main/resources/data/arcanecircle/spell_catalog/index.json"
index = json.loads(index_path.read_text(encoding="utf-8"))
index["version"] = NEW_VERSION
index["release_geometry"] = "bounded_primitive_batches"
index["performance_guard"] = {
    "voxel_boolean_unions": 0,
    "charge_primitive_cap": 320,
    "release_primitive_cap": 512,
    "frame_primitive_cap": 1024,
    "charge_progress_steps": 20
}
index_path.write_text(json.dumps(index, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

for name in ("test_magic_contract.py", "test_v12_overhaul.py", "test_v12_1_cleanup.py"):
    path = TOOLS / name
    text = path.read_text(encoding="utf-8").replace(OLD_VERSION, NEW_VERSION)
    if name == "test_magic_contract.py":
        text = text.replace(
            "apply_v0121_alpha2_signature_geometry.py",
            "apply_v0121_alpha3_freeze_hotfix.py")
    path.write_text(text, encoding="utf-8")

print("Arcane Circle v0.12.1-alpha.3 casting freeze hotfix installed")
